{"results": [{"id": "FAM:SF-APPS-025", "label": "Study family SF-APPS-025: Adapt vs continue matched-pair overall-offense excess (post-hoc)", "score": 1.108, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-025 (0.75)", "request matches RQC:RQC-036 (0.71); FAM:SF-APPS-025 auto_addresses_question RQC:RQC-036"], "attributes": {"observed_research_question": "Adapt vs continue matched-pair overall-offense excess (post-hoc)", "auto_outcome_status": "untestable", "observed_hypothesis": "Teams that abandon a suppressed play type (h2_n<=1) show a smaller matched-pair overall six-PT H1->H2 excess decline than teams that continue (h2_n>=5).", "observed_result": "Caliper 0.10: A excess +0.076 [+0.068,+0.084] n=3421 p=0; B excess +0.014 [-0.019,+0.046] n=255 p=0.386. Gap B-A = -0.062. Caliper sweep B CIs include 0 except 0.15.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Group B caliper-0.10 CI includes 0 (p=0.386, n=255 clusters=242); Group B is a reconstructed post-hoc cohort, not a validated successful-adaptation sample.", "observed_sample_and_power": "B n=255 pairs / 242 games at primary caliper"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF14"}]}, {"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 1.059, "reached_via": ["FAM:SF-APPA-005 auto_related_family (record_link_related_to) FAM:SF-APPA-001", "FAM:SF-APPA-005 auto_related_family (limitation_precedent) FAM:SF-APPA-001"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPA-015", "label": "Study family SF-APPA-015: A3 equilibrium vs actual significance test", "score": 0.758, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-015 (0.76)"], "attributes": {"observed_research_question": "A3 equilibrium vs actual significance test", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Matchup-aware equilibrium beats actual team behavior significantly across matchups.", "observed_result": "A3 beats actual 138/240 (57.5%); weighted mean +2.06 pts/100; median +2.22; SD 14.26; t=2.24; p=0.0644.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Doc reports p=0.064 not significant.", "observed_sample_and_power": "n=240, SD 14.26 pts/100", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Per-matchup A3 minus actual across 240 matchups; t-test.", "observed_verdict": "null", "observed_failure_type": "E_unclear", "observed_notes": "t=2.24 with n=240 should give p about 0.026 two-sided, so the stated p and t disagree. A3 PPP is nearly constant per offense, e.g. OKC 1.356 against every opponent."}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-011"}]}, {"id": "FAM:SF-APPS-015", "label": "Study family SF-APPS-015: Player BEST/AVOID tier tendency in H2 trigger games (55 series)", "score": 0.756, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-015 (0.76)"], "attributes": {"observed_research_question": "Player BEST/AVOID tier tendency in H2 trigger games (55 series)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Teams and players differ in how often H2 trigger possessions land on the engine's BEST vs AVOID counter.", "observed_result": "Team AVOID% ranges 50.6% (ORL) to 6.8% (SAC); team BEST% 0.0%-15.8%.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No outcome test; player samples 10-178 possessions.", "observed_sample_and_power": "min 10 poss per player", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "trigger_table_clean.csv, 55 series 2022-2026, 179 players, 25 teams, min 10 poss.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-048"}, {"rel": "auto_addresses_question", "node": "RQC:RQC-001"}]}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.754, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-005 (0.75)"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}, {"id": "FAM:SF02", "label": "Study family SF02: Offenses continue suppressed plays (volume and cost)", "score": 0.731, "reached_via": ["FAM:SF-APPS-025 auto_related_family (record_link_related_to) FAM:SF02", "request matches RQC:RQC-036 (0.71); FAM:SF02 auto_addresses_question RQC:RQC-036"], "attributes": {"observed_research_question": "Offenses continue suppressed plays (volume and cost)", "auto_outcome_status": "supported", "observed_hypothesis": "Once a play type is suppressed, teams cut its second-half volume.", "observed_result": ["[APPA-040] PO: 735 events; Group A 683 (93%) H1 1.522 to H2 0.876, cost/poss 0.646, ~8.2 H2 poss, ~97% H1 volume, ~5.4 pts/trigger; real actionable ~6.1 pts (5.3 keep-calling + 0.8 AVOID vs BEST). RS continue 93.1% (2,94 [cut; read_family for the full text]", "[APPS-021] Group A: H1 1.522 -> post-trigger 0.876, cost 0.646 PPP/poss, 5.16 pts/trigger (t=48.172, p=0.0000, n=683). Pivot vs continue overall H2 1.074 vs 1.043, MW p=0.2642. Locked row-mean (n>=5): H1 1.48->H2 0.85, d [cut; read_family for the full text]", "[CHT-040] H1-H2 drop t=48.172 p=0.0000 (n=683). Pivoting improve H2? Mann-Whitney p=0.2642 (not significant)."], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": []}, {"id": "FAM:SF-APPA-058", "label": "Study family SF-APPA-058: Season stability of top suppressors and negative teammate pairs", "score": 0.457, "reached_via": ["request matches RQC:RQC-072 (0.72); FAM:SF-APPA-058 auto_addresses_question RQC:RQC-072"], "attributes": {"observed_research_question": "Season stability of top suppressors and negative teammate pairs", "auto_outcome_status": "rejected", "observed_hypothesis": "Each star's top sequential suppressor is stable across seasons, and some teammate X->Y sequences have large negative premiums.", "observed_result": "2/30 (7%) stable (>=75% same top suppressor): D. Mitchell PUTBACK 75%, L. James POST_UP 75%. Negative: J. Tatum->K. Porzingis DRIVE->SPOT_UP -0.444 n=31; Giannis->Lillard DRIVE->PNR -0.263 n=31; J. Brown->J. Tatum SPOT_U [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Only 2/30 stars meet the 75% same-top-suppressor stability rule.", "observed_sample_and_power": "30 stars x 4 seasons; min n=20/cell", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 0.447, "reached_via": ["request matches RQC:RQC-129 (0.71); FAM:SF-CHT-039 auto_addresses_question RQC:RQC-129"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-012", "label": "Study family SF-APPS-012: Defensive PPP allowed and possession share, RS vs playoffs", "score": 0.446, "reached_via": ["request matches RQC:RQC-101 (0.71); FAM:SF-APPS-012 auto_addresses_question RQC:RQC-101"], "attributes": {"observed_research_question": "Defensive PPP allowed and possession share, RS vs playoffs", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Playoff defenses suppress DRIVE more than RS defenses (both lower PPP allowed and lower share).", "observed_result": "DRIVE allowed 1.191 -> 0.923 (-0.268), share 21.2% -> 18.2%; PNR -0.139, share +12.1pp; PULL_UP +0.341, share -7.6pp.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test; PNR share jump of +12.1pp may reflect tagging differences.", "observed_sample_and_power": "25 teams", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "25 defensive teams, min 30 poss per cell; RS vs playoff PPP allowed and opponent possession share by PT.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPA-011", "label": "Study family SF-APPA-011: Matchup-aware A3 vs team kernel A2 at equilibrium", "score": 0.379, "reached_via": ["FAM:SF-APPA-015 auto_related_family (record_link_related_to) FAM:SF-APPA-011"], "attributes": {"observed_research_question": "Matchup-aware A3 vs team kernel A2 at equilibrium", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Player-vs-defender matchup modeling (A3) improves equilibrium PPP over team-level A2.", "observed_result": "V2: A3 +2.50 vs A2 +1.16 pts/100, A3 beats A2 147/240. V3: A2 +8.84, A3 +2.06, A3-A2 -6.78, A3 beats A2 71/240. V3_SHUFFLED: A2 +8.61, A3 +1.59, -7.02.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Sign flips from +1.34 (V2) to -6.78 (V3) when spatial sub-types were added.", "observed_sample_and_power": "240 matchups", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Same 240 matchups; V2 coarse play types; V3 adds spatial sub-types; V3_SHUFFLED re-run (what was shuffled is not documented)."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-012"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-012"}]}], "n_results": 10}

